// Part 4, Slate roof: roof.json (granary, slate, footprint 2,3,21,34;21,3,40,34, y 24, keep the gable cells) is laid
// by runParts right after the shell, so this part only adds the ridge monitor vents. Each vent sits ON the ridge cap
// (the cap is at y 35), so it writes into air above the roof and never into the roof's own cells.
import { monitorVent } from "../vocab.mjs";

// the two ridges: twin columns at the middle of each gable roof (plan HOIST_X line)
const RIDGES = [[11, 12], [30, 31]];
// the vent runs along the ridge, clear of the eaves at each end
const VENT_Y = 36, VENT_Z0 = 8, VENT_Z1 = 29;

export function build(g) {
  for (const [x0, x1] of RIDGES) monitorVent(g, x0, x1, VENT_Y, VENT_Z0, VENT_Z1);
}

